function OverseaManagePersonnelCatBallDialog:OnCatManagePutOn(data)
    self:RefreshCatShow()
    self:RequestShow()
    if data.isFirst == 1 then
        ---@type CatBallUtils
        local CatBallUtils = import("Game.CatBall.CatBallUtils")
        local time = CatBallUtils.GetCatBallParams(12)
        self:RemoveRewardTimer()
        self.rewardTimer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
            if count <= 0 then
                self:RemoveRewardTimer()
                self:RequestShow()
            end
        end, checkNumber(time), false, true)
    end
end

function OverseaManagePersonnelCatBallDialog:RemoveRewardTimer()
    if self.rewardTimer then
        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.rewardTimer)
        self.rewardTimer = nil
    end
end

function OverseaManagePersonnelCatBallDialog:RequestShow()
    GameUtils.Request(Interfaces.MaidCoffeeCatBallReward,{},function(request,response)
        if checkNumber(response.errCode) == 0 then
            local data = response.data
            self:RefreshRightUIShow(data)
            self:RefreshRedPoint(data)
            KTool.SetActive(self.Root.gameObject,true)
        end
    end)
end

function OverseaManagePersonnelCatBallDialog:RefreshRightUIShow(data)
    local aniName = "OverseaManagePersonnelCatballDialog_BlueLoop"
    local time = self:GetDurationTime()
    self:RemoveTimer()
    if data.status == RewardStatus.NoStart then
        CfUtils.SetUISwitchText(self.TextDesc,1)
        CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS(0))
    elseif data.status == RewardStatus.Starting then
        CfUtils.SetUISwitchText(self.TextDesc,2)
        local duration = data.duration
        CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS(duration))
        if duration < time then
            self.Timer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
                if count > 0 then
                    duration = duration + 1
                    CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS(duration))
                else
                    self:RemoveTimer()
                    CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS(time))
                    self:RequestShow()
                end
            end, time - duration, false, true)
        end
    elseif data.status == RewardStatus.Parse then
        CfUtils.SetUISwitchText(self.TextDesc,2)
        CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS(checkNumber(data.duration)))
    elseif data.status == RewardStatus.UpLimit then
        CfUtils.SetUISwitchText(self.TextDesc,3)
        CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS(checkNumber(data.duration)))
        aniName = "OverseaManagePersonnelCatballDialog_redLoop"
    else
        printError("错误的状态 状态：%s  请联系服务器检查",data.status)
    end

    CfUtils.SetActive(self.ImgMax,data.status == RewardStatus.UpLimit)
    CfUtils.FillText(self.LimitTimeText,CfUtils.GetTimeHMS5(time))
    self.RightPanelAni:Play(aniName)
    self:RefreshRewardShow(data.rewards,data.status)
    self:SetTipDes()
end

function OverseaManagePersonnelCatBallDialog:RefreshRedPoint(data)
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local isHaveRedPoint = false
    local isTimeMax = data.status == RewardStatus.UpLimit
    local isPutCat = component:IsHaveCatToPutOn()
    isHaveRedPoint = isTimeMax or isPutCat
    GameUtils.UpdateServerRedPointData({cafeCatBall = isHaveRedPoint and 0 or -1})
end

function OverseaManagePersonnelCatBallDialog:SetTipDes()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local isCafeMax = maidCoffeePlayerComponent:IsToMaxCafeLevel()
    local cafeLevel = component:GetMaidCoffeeLevel()
    KTool.SetActive(self.Next.gameObject,not isCafeMax)

    local time = self:GetDurationTime()
    local curTime = CfUtils.GetTimeHMS5(time)
    CfUtils.FillText(self.CurTextTime,curTime)
    local curTxt = isCafeMax and localize("当前餐厅已满级，寻宝时间上限为：") or localize("当前餐厅_level1_级，寻宝时间上限为：",{_level1_ = cafeLevel})
    CfUtils.FillText(self.CurDesc,curTxt)
    if not isCafeMax then
        local nextTxt = localize("下一级，寻宝时间上限为：")
        CfUtils.FillText(self.NextDesc,nextTxt)
        local nextTime = self:GetDurationTime(true)
        CfUtils.FillText(self.NextTextTime,string.format("<color=#ff1cae>%s</color>",CfUtils.GetTimeHMS5(nextTime)))
   end
end

function OverseaManagePersonnelCatBallDialog:RemoveTimer()
