        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
        self.Timer = nil
    end
end

function OverseaManagePersonnelCatBallDialog:RefreshRewardShow(rewards,status)
    self.rewards = rewards
    local isHaveReward = table.count(self.rewards) > 0
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidHomeDoJo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    if maidHomeDoJo then
        local state = isHaveReward and 1 or 0
        maidHomeDoJo:UpdateCatBallStatus(state)
    end
    KTool.SetActive(self.RewardSV.gameObject,isHaveReward)
    KTool.SetActive(self.Empty.gameObject,not isHaveReward)
    if isHaveReward then
        if not self.RewardSV.IsListViewInit then
            self.RewardSV:InitGridView(table.count(rewards), Bind(self, self.OnRewardGetItemByIndex))
        else
            GameUtils.ReloadData(self.RewardSV, table.count(rewards))
        end
    else
        ---一般只有没有猫球的时候 才会是未开始
        if status == RewardStatus.NoStart then
            CfUtils.SetUISwitchText(self.Text,1)
        else
            CfUtils.SetUISwitchText(self.Text,2)
        end
    end
end

function OverseaManagePersonnelCatBallDialog:CalculationTipsPos()
    -- 计算targetNode在UI坐标系里的坐标
    local cam = UIModule.RootCanvas.defaultCamera
    local topLayerRt = UIModule.RootCanvas.transform:GetComponent("RectTransform")
    local screenPoint = CS.UnityEngine.RectTransformUtility.WorldToScreenPoint(cam, self.BtnExplain.transform.position)
    local _, targetNodeUIPos = CS.UnityEngine.RectTransformUtility.ScreenPointToLocalPointInRectangle(topLayerRt, screenPoint, cam)
    local content = self.Bg.transform
    content.localPosition = Vector3.New(targetNodeUIPos.x - 20, content.localPosition.y, 0)
end

function OverseaManagePersonnelCatBallDialog:OnRewardGetItemByIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    if table.count(self.rewards) < (index + 1) then
        return nil
    end

    local cell = listView:NewListViewItem(CatCell)
    if not isNull(cell) then
        local goodNode = cell.transform:Find("GoodNode")
        if not isNull(goodNode) then
            local env = CfUtils.GetLuaScr(goodNode,GoodNodeMBPath)
            if env then
                env:Reload({
                    goodsId = self.rewards[index + 1].goodsId ,
                    isShowNo = true,
                    text = self:GetText(true, self.rewards[index + 1].num,self.rewards[index + 1].goodsId , false),
                })
                env:SetClickButtonAction(function(goodsId, id)
                    ----点击出gip
                    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                    if isTable(vo) then
                        GameUtils.ShowCommonTipsBoard(goodNode, vo.name, vo.desc, vo.quality, vo.id)
                    end
                end)
            end
        end
    end
    return cell
end

function OverseaManagePersonnelCatBallDialog:GetText(isShowNum, num, goodsId, isCheckNum)
    if not isShowNum then
        return nil
    end
    if isCheckNum then
        return GoodsUtils.GetGoodsText(goodsId, num, 1) --- GoodsUtils.GetConsumeGoodsText(goodsId, num)
    end
    return 'x' .. FormatCurrencyNum(num)
end

function OverseaManagePersonnelCatBallDialog:GetDurationTime(nextLevel)
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local cafeLevel = component:GetMaidCoffeeLevel()
    if nextLevel then
        cafeLevel = cafeLevel + 1
    end
    local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")
    local vo = MaidCoffeeUtils.GetMaidCoffeeLevelExpVo(cafeLevel)
    return vo.catTime or 0
end

function OverseaManagePersonnelCatBallDialog:RefreshCatShow()
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitGridView(MaidCoffeeConstants.MaidCoffeeCatCount, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, MaidCoffeeConstants.MaidCoffeeCatCount)
    end
end

function OverseaManagePersonnelCatBallDialog:OnGetItemByIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    if MaidCoffeeConstants.MaidCoffeeCatCount < (index + 1) then
        return nil
    end

    local cell = listView:NewListViewItem(CatCell)
    if not isNull(cell) then
        local env = CfUtils.GetLuaScr(cell,CatCellPath)
        if env then
            env:RefreshCatShow(index + 1)
            env:SetShowCatCallBack(function(showEffectId)
                self.showEffectId = showEffectId
                self:RefreshCatShow()
            end)
            local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
            local ownerId = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Cat ,index + 1)
            env:PlayShowEffect(false)
            if self.showEffectId and self.showEffectId ~= 0 then
                if ownerId == self.showEffectId then
                    env:PlayShowEffect(true)
                    self.showEffectId = nil
                end
            end
        end
    end
    return cell
end

function OverseaManagePersonnelCatBallDialog:OnBtnExplainClick()
    self:CalculationTipsPos()
    KTool.SetActive(self.Tips.gameObject,not self.Tips.gameObject.activeSelf)
end

function OverseaManagePersonnelCatBallDialog:OnBtnEmptyCloseClick()
