end

function OverseaManagePersonnelCatBallDialog:OnBtnGetCatBallClick()
    local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(MaidCoffeeConstants.CatBallJumpRowId)
    GoodsConfMgr:GetInstance():ExecuteJump(row)
end

function OverseaManagePersonnelCatBallDialog:OnBtnExplainClickClick()
    if table.count(self.rewards) > 0 then
        GameUtils.Request(Interfaces.MaidCoffeeCatBallDrawReward,{},function(request,response)
            if checkNumber(response.errCode) == 0 then
                local data = response.data
                GoodsUtils.DrawRewards(data.rewards, true)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = data.rewards,cb = function()
                    self:RequestShow()
                end } })
            end
        end)
    else
        GameUtils.Toast(localize("当前还没有搜集到食材"))
    end
end

function OverseaManagePersonnelCatBallDialog:OnBtnRuleClick()
    UIModule.OpenDialog({ id = Constants.UITypeIds.OverseaCatBallFoodShow})
end
return OverseaManagePersonnelCatBallDialog